/**
 * Document is a file opened in the editor. File I/O lives in Go so the
 * frontend never touches the filesystem. Content holds text for text documents;
 * Src holds a data URL for images.
 */
export interface Document {
    "path": string;

    /**
     * RealPath is Path with every symlink resolved. Tabs match on it, so the
     * same file opened through a link and through its real path is one tab,
     * while Path keeps the spelling the user opened for display.
     */
    "real_path": string;
    "name": string;
    "kind": string;
    "content": string;
    "src": string;

    /**
     * Modified is the file's mtime in Unix milliseconds when the content was
     * read. The frontend hands it back on save, so a write never silently
     * overwrites a change another program made. Milliseconds, not nanoseconds:
     * the value travels through JavaScript, whose numbers lose precision above
     * 2^53.
     */
    "modified": number;

    /**
     * BOM records a UTF-8 byte order mark that was stripped from the content.
     * SaveDocument puts it back so a round trip never rewrites the file's
     * encoding.
     */
    "bom": boolean;

    /**
     * EOL is the file's line ending: "lf" or "crlf". Mixed endings are
     * reported as whichever comes first and are normalized to it on save.
     */
    "eol": string;

    /**
     * InvalidUTF8 marks content that was not valid UTF-8. The bytes became
     * replacement characters, and a save must warn before it drops them.
     */
    "invalid_utf8": boolean;
}

/**
 * SaveRequest is one buffer on its way to disk. ExpectedModified is the mtime
 * LoadDocument reported for the file the buffer was read from; a mismatch means
 * another program wrote it in the meantime, and nothing is written. Overwrite
 * skips that check, once the user has been told.
 */
export interface SaveRequest {
    "path": string;
    "content": string;
    "expected_modified": number;
    "overwrite": boolean;

    /**
     * BOM and EOL are the file's encoding as LoadDocument reported it. The
     * content itself is normalized by Monaco, so a save restores both around
     * the text it is handed.
     */
    "bom": boolean;
    "eol": string;

    /**
     * InvalidUTF8 marks a buffer whose file was not valid UTF-8. Writing it
     * replaces the original bytes with U+FFFD, so the save returns without
     * writing until AllowInvalidUTF8 says the user agreed.
     */
    "invalid_utf8": boolean;
    "allow_invalid_utf8": boolean;
}

/**
 * SaveResult reports what a save did. A Conflict means the buffer was not
 * written and the user has to decide whether to overwrite; InvalidUTF8 means
 * the buffer holds replacement characters and the user has to agree to lose
 * them. The other fields are then the file that caused it. Path and Name
 * describe where the text belongs, so Save As can move a buffer to its new home
 * in one step.
 */
export interface SaveResult {
    "path": string;

    /**
     * RealPath is Path with every symlink resolved, so the frontend can match
     * the saved file against the tabs it already has (an alias of an open file
     * is the same file).
     */
    "real_path": string;
    "name": string;
    "modified": number;
    "conflict": boolean;
    "invalid_utf8": boolean;
}
